  "leiden-imaging": {zarFunding:"≈ R59,700–R75,500 gross/month",officialUrl:"https://careers.universiteitleiden.nl/job/PhD-in-Computational-Imaging-for-High-Throughput-Applications-(1_0-fte)/16832-en_US",portalUrl:"https://careers.universiteitleiden.nl/job/PhD-in-Computational-Imaging-for-High-Throughput-Applications-(1_0-fte)/16832-en_US",portalLabel:"Official vacancy & apply"},
