  "mpi-cvml": {zarFunding:"Exact funding terms to confirm",officialUrl:"https://www.mpi-inf.mpg.de/departments/computer-vision-and-machine-learning/application/phd-applications",portalUrl:"https://www.mpi-inf.mpg.de/departments/computer-vision-and-machine-learning/application/phd-applications",portalLabel:"Official instructions"}
