const seedOpportunities: Opportunity[] = baseOpportunities.map(item=>({...item,...opportunityEnrichment[item.id]}));

const masterDocuments = ["Academic CV tailored for PhD applications","BSc degree certificate","BSc full transcript","Current MSc transcript","MSc registration/enrolment proof","Official expected-completion or completion letter from UWC","One-page MSc thesis summary","Publication list with DOI and links","Google Scholar and ORCID links","GitHub profile with presentable research/code projects","Two or three referees who have agreed to be contacted","Master motivation-letter building blocks","Master research statement","Degree grading-scale explanation","Passport scan for later immigration/admin stages"];
const statusOptions: Status[] = ["Not started","Preparing","Ready","Submitted","Interview","Closed"];
const deadlineTime = (o:Opportunity) => o.deadline ? new Date(o.deadline).getTime() : Number.POSITIVE_INFINITY;
const daysRemaining = (d:string|null) => d ? Math.ceil((new Date(d).getTime()-Date.now())/86_400_000) : null;
const escapeCsv = (v:unknown) => `"${String(v??"").replaceAll('"','""')}"`;

export default function Home() {
  const [opportunities,setOpportunities]=useState<Opportunity[]>(seedOpportunities);
  const [checks,setChecks]=useState<Record<string,boolean>>({});
  const [search,setSearch]=useState("");
  const [fitFilter,setFitFilter]=useState("all");
  const [expanded,setExpanded]=useState<Record<string,boolean>>({"ku-leuven-compliance":true});
  const [dialogOpen,setDialogOpen]=useState(false);
  const [newOpportunity,setNewOpportunity]=useState({title:"",institution:"",country:"",deadline:"",url:""});
  const [hydrated,setHydrated]=useState(false);
  useEffect(()=>{try{const a=localStorage.getItem(STORAGE_KEY),b=localStorage.getItem(CHECK_KEY);if(a){const saved:Opportunity[]=JSON.parse(a);const savedById=new Map(saved.map(item=>[item.id,item]));const refreshed=seedOpportunities.map(item=>{const previous=savedById.get(item.id);return previous?{...item,status:previous.status,notes:previous.notes}:item});const custom=saved.filter(item=>!seedOpportunities.some(seed=>seed.id===item.id));setOpportunities([...refreshed,...custom]);}if(b)setChecks(JSON.parse(b));}catch{} setHydrated(true);},[]);
  useEffect(()=>{if(hydrated)localStorage.setItem(STORAGE_KEY,JSON.stringify(opportunities));},[hydrated,opportunities]);
  useEffect(()=>{if(hydrated)localStorage.setItem(CHECK_KEY,JSON.stringify(checks));},[checks,hydrated]);
  const filtered=useMemo(()=>{const q=search.trim().toLowerCase();return [...opportunities].filter(i=>(!q||`${i.title} ${i.institution} ${i.country} ${i.tags.join(" ")}`.toLowerCase().includes(q))&&(fitFilter==="all"||i.fit>=Number(fitFilter))).sort((a,b)=>deadlineTime(a)-deadlineTime(b)||b.fit-a.fit)},[opportunities,search,fitFilter]);
  const submitted=opportunities.filter(i=>i.status==="Submitted"||i.status==="Interview").length;
  const urgent=opportunities.filter(i=>i.window==="urgent"&&i.status!=="Submitted").length;
  const highFit=opportunities.filter(i=>i.fit>=9).length;
  const documentProgress=masterDocuments.filter((_,i)=>checks[`master-${i}`]).length;
  const updateOpportunity=(id:string,patch:Partial<Opportunity>)=>setOpportunities(c=>c.map(i=>i.id===id?{...i,...patch}:i));
  function addOpportunity(){if(!newOpportunity.title.trim()||!newOpportunity.institution.trim())return;const d=newOpportunity.deadline?`${newOpportunity.deadline}T23:59:00Z`:null;setOpportunities(c=>[...c,{id:`custom-${Date.now()}`,title:newOpportunity.title.trim(),institution:newOpportunity.institution.trim(),country:newOpportunity.country.trim()||"To verify",deadline:d,deadlineLabel:newOpportunity.deadline||"To verify",window:"later",fit:0,funding:"To verify",zarFunding:"To verify",start:"To verify",msc:"To verify",applyUrl:newOpportunity.url.trim()||"#",officialUrl:newOpportunity.url.trim()||undefined,portalLabel:"Verify application route",source:"Added manually — not yet verified",tags:["Needs research"],whyFit:"Not yet assessed.",caution:"Verify the official posting, deadline, funding and eligibility before applying.",action:"Research and score this opportunity.",documents:["Required documents to verify"],status:"Not started",custom:true}]);setNewOpportunity({title:"",institution:"",country:"",deadline:"",url:""});setDialogOpen(false)}
  function exportData(format:"json"|"csv"){const body=format==="json"?JSON.stringify({exportedAt:new Date().toISOString(),opportunities,checks},null,2):[["Institution","Position","Country","Deadline","Fit","Funding","Approx ZAR","Possible start","Status","Official details","Application portal"].map(escapeCsv).join(","),...opportunities.map(i=>[i.institution,i.title,i.country,i.deadlineLabel,i.fit,i.funding,i.zarFunding,i.start,i.status,i.officialUrl??i.applyUrl,i.portalUrl??i.applyUrl].map(escapeCsv).join(","))].join("\n");const blob=new Blob([body],{type:format==="json"?"application/json":"text/csv"});const url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download=`mayimunah-application-tracker.${format}`;a.click();URL.revokeObjectURL(url)}

  function OpportunityCard({item}:{item:Opportunity}){
    const isExpanded=expanded[item.id],remaining=daysRemaining(item.deadline),completed=item.documents.filter((_,i)=>checks[`${item.id}-${i}`]).length;
    return <article className="group overflow-hidden rounded-[1.35rem] border border-[var(--line)] bg-white shadow-[0_10px_40px_rgba(20,36,57,0.06)] transition hover:-translate-y-0.5 hover:shadow-[0_16px_48px_rgba(20,36,57,0.10)]">
      <div className="p-5 sm:p-6"><div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div className="min-w-0"><div className="mb-3 flex flex-wrap items-center gap-2"><Badge className={item.fit>=9?"bg-[#163e5c] text-white":item.fit>=8?"bg-[#d9efe8] text-[#155348]":"bg-[#eef1f4] text-[#53606b]"}>{item.fit?`${item.fit.toFixed(1)}/10 fit`:"Unscored"}</Badge>{item.window==="urgent"&&<Badge className="bg-[#fff0e8] text-[#a44720]">Apply this week</Badge>}{!item.deadline&&<Badge variant="outline">Rolling</Badge>}</div><h3 className="max-w-3xl text-[1.16rem] font-semibold leading-snug text-[#13283a] sm:text-[1.28rem]">{item.title}</h3><div className="mt-2 flex flex-wrap items-center gap-x-4 gap-y-1 text-sm text-[#607080]"><span className="font-medium text-[#334b5f]">{item.institution}</span><span className="inline-flex items-center gap-1"><MapPin className="size-3.5"/>{item.country}</span><span className="inline-flex items-center gap-1"><CalendarDays className="size-3.5"/>{item.deadlineLabel}</span></div></div><div className="flex shrink-0 flex-wrap items-center gap-2">{remaining!==null&&remaining>=0&&<span className={remaining<=4?"rounded-full bg-[#9d3520] px-3 py-2 text-sm font-semibold text-white":"rounded-full bg-[#edf3f7] px-3 py-2 text-sm font-semibold text-[#314f67]"}>{remaining===0?"Due today":`${remaining} day${remaining===1?"":"s"} left`}</span>}<Select value={item.status} onValueChange={v=>updateOpportunity(item.id,{status:v as Status})}><SelectTrigger className="w-[142px] border-[#ced8df] bg-white"><SelectValue/></SelectTrigger><SelectContent>{statusOptions.map(s=><SelectItem value={s} key={s}>{s}</SelectItem>)}</SelectContent></Select></div></div>
      <div className="mt-4 flex flex-wrap gap-2">{item.tags.map(t=><span key={t} className="rounded-full bg-[#f2f5f6] px-2.5 py-1 text-xs font-medium text-[#536572]">{t}</span>)}</div>
      <div className="mt-5 grid gap-3 border-y border-[#e7ecef] py-4 sm:grid-cols-3"><div><p className="micro-label">Funding</p><p className="mt-1 text-sm font-medium text-[#243c4d]">{item.funding}</p>{item.zarFunding&&<p className="mt-1 text-xs font-semibold leading-5 text-[#a44f2c]">{item.zarFunding}</p>}</div><div><p className="micro-label">Possible start</p><p className="mt-1 text-sm font-medium text-[#243c4d]">{item.start}</p></div><div><p className="micro-label">Documents</p><p className="mt-1 text-sm font-medium text-[#243c4d]">{completed}/{item.documents.length} ready</p></div></div>
      {item.portalNote&&<div className="mt-4 rounded-xl border border-[#f0d8ca] bg-[#fff8f4] px-4 py-3 text-xs leading-5 text-[#754632]"><strong>Portal note:</strong> {item.portalNote}</div>}
      <div className="mt-4 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between"><p className="text-sm leading-6 text-[#4e6372]"><span className="font-semibold text-[#1c3d54]">Next move:</span> {item.action}</p><div className="flex shrink-0 flex-wrap gap-2"><Button variant="outline" size="sm" onClick={()=>setExpanded(c=>({...c,[item.id]:!isExpanded}))}>{isExpanded?<ChevronUp/>:<ChevronDown/>}{isExpanded?"Less":"Details"}</Button>{(item.officialUrl??item.applyUrl)!=="#"&&<Button variant="outline" asChild size="sm"><a href={item.officialUrl??item.applyUrl} target="_blank" rel="noreferrer">Official details <ArrowUpRight/></a></Button>}{item.portalUrl&&<Button asChild size="sm" className="bg-[#d96b3b] text-white hover:bg-[#bd5730]"><a href={item.portalUrl} target="_blank" rel="noreferrer">{item.portalLabel??"Application portal"} <ArrowUpRight/></a></Button>}{!item.portalUrl&&item.portalLabel&&<Button size="sm" disabled>{item.portalLabel}</Button>}</div></div></div>
      {isExpanded&&<div className="border-t border-[#dfe7eb] bg-[#f8fafb] p-5 sm:p-6"><div className="grid gap-6 lg:grid-cols-[1.1fr_0.9fr]"><div className="space-y-4"><section><p className="micro-label">Why it fits</p><p className="mt-2 text-sm leading-6 text-[#405766]">{item.whyFit}</p></section><section className="rounded-xl border border-[#f0d8ca] bg-[#fff8f4] p-4"><p className="flex items-center gap-2 text-sm font-semibold text-[#8b4326]"><CircleAlert className="size-4"/>Watch this</p><p className="mt-1.5 text-sm leading-6 text-[#6c4d3e]">{item.caution}</p></section><section><p className="micro-label">MSc timing</p><p className="mt-2 text-sm leading-6 text-[#405766]">{item.msc}</p></section></div><div><div className="mb-3 flex items-center justify-between"><p className="micro-label">Required document checklist</p><span className="text-xs font-semibold text-[#5d6f7b]">{completed}/{item.documents.length}</span></div><div className="space-y-2">{item.documents.map((d,i)=>{const k=`${item.id}-${i}`;return <label key={d} className="flex cursor-pointer items-start gap-3 rounded-xl border border-[#dfe7eb] bg-white p-3 text-sm leading-5 text-[#344c5d] hover:border-[#b8c9d4]"><input type="checkbox" checked={Boolean(checks[k])} onChange={e=>setChecks(c=>({...c,[k]:e.target.checked}))} className="mt-0.5 size-4 accent-[#1b5b72]"/><span className={checks[k]?"text-[#72808a] line-through":""}>{d}</span></label>})}</div></div></div><div className="mt-5 grid gap-3 sm:grid-cols-[1fr_auto] sm:items-end"><label><span className="micro-label">Private notes</span><Textarea className="mt-2 min-h-20 border-[#ced8df] bg-white" value={item.notes??""} onChange={e=>updateOpportunity(item.id,{notes:e.target.value})} placeholder="Contacts, questions, draft status, portal notes…"/></label><a href={item.officialUrl??item.applyUrl} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 pb-3 text-sm font-semibold text-[#1b5b72] hover:underline"><Link2 className="size-4"/>{item.source}</a></div></div>}
    </article>
  }
  const listForWindow=(w?:WindowName)=>filtered.filter(i=>!w||i.window===w);
  return <main className="min-h-screen bg-[var(--background)] text-[var(--foreground)]"><div className="top-rule"/><div className="mx-auto max-w-[1480px] px-4 pb-16 pt-6 sm:px-6 lg:px-8">
    <header className="mb-6 flex flex-col gap-5 rounded-[1.65rem] border border-[#dce5e9] bg-[#f9fbfb]/95 p-5 shadow-[0_18px_60px_rgba(21,45,61,0.08)] sm:p-7 lg:flex-row lg:items-center lg:justify-between"><div><div className="mb-2 flex items-center gap-2 text-xs font-bold uppercase tracking-[0.18em] text-[#c05a33]"><Target className="size-4"/>Application command centre</div><h1 className="font-display text-3xl font-semibold tracking-tight text-[#112c40] sm:text-4xl">Mayimunah’s 2026–27 opportunity tracker</h1><p className="mt-2 max-w-3xl text-[0.98rem] leading-6 text-[#587080]">23 researched PhD and research opportunities, ordered by deadline and strategic fit. Official details and application routes are separated clearly. Research checked 2 September 2026.</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>exportData("csv")}><Download/>CSV</Button><Button variant="outline" onClick={()=>exportData("json")}><Download/>Backup</Button><Dialog open={dialogOpen} onOpenChange={setDialogOpen}><DialogTrigger asChild><Button className="bg-[#163e5c] text-white hover:bg-[#0d3049]"><Plus/>Add opportunity</Button></DialogTrigger><DialogContent><DialogHeader><DialogTitle>Add an opportunity</DialogTitle><DialogDescription>Add the basics now. Unverified fields will be clearly marked for research.</DialogDescription></DialogHeader><div className="grid gap-3 py-2"><Input placeholder="Position title" value={newOpportunity.title} onChange={e=>setNewOpportunity({...newOpportunity,title:e.target.value})}/><Input placeholder="University or organisation" value={newOpportunity.institution} onChange={e=>setNewOpportunity({...newOpportunity,institution:e.target.value})}/><Input placeholder="Country" value={newOpportunity.country} onChange={e=>setNewOpportunity({...newOpportunity,country:e.target.value})}/><Input type="date" value={newOpportunity.deadline} onChange={e=>setNewOpportunity({...newOpportunity,deadline:e.target.value})}/><Input type="url" placeholder="Official vacancy URL" value={newOpportunity.url} onChange={e=>setNewOpportunity({...newOpportunity,url:e.target.value})}/></div><DialogFooter><Button onClick={addOpportunity}>Save opportunity</Button></DialogFooter></DialogContent></Dialog></div></header>
    <div className="mb-6 rounded-2xl border border-[#d7e4e8] bg-white px-4 py-3 text-xs leading-5 text-[#5b6f7d]"><strong className="text-[#1f435a]">Rand estimates:</strong> indicative mid-market conversions checked 2 September 2026 (EUR R18.63, CHF R19.76, AUD R11.50, CAD R11.56, NZD R9.36, SEK R1.68). They are comparison aids—not take-home pay—and exclude tax, fees and exchange-rate movement unless marked tax-free.</div>
    <section className="mb-6 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[{icon:Clock3,value:urgent,label:"applications due this week",tone:"coral"},{icon:Sparkles,value:highFit,label:"high-fit opportunities",tone:"blue"},{icon:Check,value:submitted,label:"submitted or interviewing",tone:"green"},{icon:FileCheck2,value:`${documentProgress}/${masterDocuments.length}`,label:"master documents ready",tone:"ink"}].map(({icon:Icon,value,label,tone})=><Card key={label} className={`metric-card metric-${tone}`}><CardContent className="flex items-center gap-4 p-5"><div className="metric-icon"><Icon/></div><div><p className="text-2xl font-bold tracking-tight">{value}</p><p className="text-sm opacity-80">{label}</p></div></CardContent></Card>)}</section>
    <section className="mb-6 grid gap-4 lg:grid-cols-[1.05fr_0.95fr]"><div className="rounded-[1.4rem] bg-[#153b56] p-5 text-white sm:p-6"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[0.16em] text-[#a8d8d0]"><ListChecks className="size-4"/>This week · 2–5 September</div><h2 className="mt-3 font-display text-2xl font-semibold">Quality sprint: two core applications, one stretch</h2><ol className="mt-5 grid gap-3 text-sm sm:grid-cols-3"><li className="action-step"><span>1</span><div><strong>KU Leuven first</strong><p>Update CV, attach transcript, write the personal half-page motivation, submit.</p></div></li><li className="action-step"><span>2</span><div><strong>Leiden second</strong><p>Confirm two referees, write the one-page motivation, submit.</p></div></li><li className="action-step"><span>3</span><div><strong>Oulu is the stretch</strong><p>Proceed only if the three-page research plan can be genuinely strong.</p></div></li></ol></div><div className="rounded-[1.4rem] border border-[#edd6c8] bg-[#fff8f3] p-5 sm:p-6"><div className="flex items-center gap-2 text-xs font-bold uppercase tracking-[0.16em] text-[#a5502d]"><CalendarDays className="size-4"/>Next week · 7–13 September</div><h2 className="mt-3 font-display text-2xl font-semibold text-[#4f2c20]">Marburg must be submitted before the weekend</h2><div className="mt-4 grid gap-2 text-sm text-[#6f4c3e]"><p><strong>Mon–Tue:</strong> Marburg motivation + CV tailoring.</p><p><strong>Wed:</strong> certificates/transcripts + portal review.</p><p><strong>Thu–Fri:</strong> submit Marburg; begin DTU and ELLIS supervisor research.</p><p><strong>Rolling slot:</strong> prepare Luxembourg World Models after Marburg is safe.</p></div></div></section>
    <Tabs defaultValue="urgent" className="gap-5"><div className="sticky top-0 z-20 -mx-1 flex flex-col gap-3 border-b border-[#dfe6ea] bg-[#f4f7f7]/95 px-1 py-3 backdrop-blur md:flex-row md:items-center md:justify-between"><TabsList className="h-auto w-full justify-start overflow-x-auto bg-[#e5ecef] p-1 md:w-auto"><TabsTrigger value="urgent" className="px-4 py-2">This week</TabsTrigger><TabsTrigger value="next" className="px-4 py-2">Next deadlines</TabsTrigger><TabsTrigger value="later" className="px-4 py-2">Later</TabsTrigger><TabsTrigger value="all" className="px-4 py-2">All</TabsTrigger><TabsTrigger value="documents" className="px-4 py-2">Document vault</TabsTrigger></TabsList><div className="flex w-full gap-2 md:max-w-[520px]"><div className="relative flex-1"><Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-[#71808b]"/><Input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search topic, country or university" className="h-10 border-[#cbd7dd] bg-white pl-9"/></div><Select value={fitFilter} onValueChange={setFitFilter}><SelectTrigger className="h-10 w-[128px] border-[#cbd7dd] bg-white"><Filter className="size-4"/><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">All fits</SelectItem><SelectItem value="9">9+ fit</SelectItem><SelectItem value="8">8+ fit</SelectItem></SelectContent></Select></div></div>
    {(["urgent","next","later","all"] as const).map(tab=><TabsContent value={tab} key={tab} className="space-y-4">{listForWindow(tab==="all"?undefined:tab).map(i=><OpportunityCard item={i} key={i.id}/>)}{listForWindow(tab==="all"?undefined:tab).length===0&&<div className="rounded-2xl border border-dashed border-[#b8c7cf] p-10 text-center text-[#647582]">No opportunities match these filters.</div>}</TabsContent>)}
    <TabsContent value="documents"><section className="grid gap-5 lg:grid-cols-[1.1fr_0.9fr]"><div className="rounded-[1.4rem] border border-[#d9e3e7] bg-white p-5 shadow-[0_12px_40px_rgba(20,36,57,0.06)] sm:p-6"><div className="flex items-start justify-between gap-4"><div><p className="micro-label">Reusable folder</p><h2 className="mt-1 font-display text-2xl font-semibold text-[#15364d]">Master document checklist</h2></div><Badge className="bg-[#d9efe8] text-[#155348]">{documentProgress}/{masterDocuments.length}</Badge></div><div className="mt-5 grid gap-2 sm:grid-cols-2">{masterDocuments.map((d,i)=>{const k=`master-${i}`;return <label key={d} className="flex cursor-pointer items-start gap-3 rounded-xl border border-[#e0e7ea] p-3 text-sm leading-5 text-[#344c5d] hover:bg-[#f7faf9]"><input type="checkbox" checked={Boolean(checks[k])} onChange={e=>setChecks(c=>({...c,[k]:e.target.checked}))} className="mt-0.5 size-4 accent-[#1b5b72]"/><span className={checks[k]?"text-[#7b878f] line-through":""}>{d}</span></label>})}</div></div><aside className="space-y-4"><div className="rounded-[1.4rem] bg-[#153b56] p-5 text-white sm:p-6"><p className="micro-label !text-[#a8d8d0]">Use this MSc wording</p><p className="mt-3 text-lg font-semibold leading-7">MSc Computer Science — expected academic completion in 2026; formal graduation ceremony in April 2027.</p><p className="mt-3 text-sm leading-6 text-[#d6e4eb]">Once UWC confirms completion, replace “expected academic completion” with the exact wording from the official completion letter.</p></div><div className="rounded-[1.4rem] border border-[#edd6c8] bg-[#fff8f3] p-5 sm:p-6"><p className="micro-label !text-[#a5502d]">Referee plan</p><ul className="mt-3 space-y-2 text-sm leading-6 text-[#654537]"><li>Ask 2–3 academics now for permission to list their details.</li><li>Only Bern needs two letters upfront among the current shortlist.</li><li>ELLIS contacts referees only for shortlisted candidates.</li><li>Never list someone who has not agreed.</li></ul></div></aside></section></TabsContent></Tabs>
    <footer className="mt-10 flex flex-col gap-2 border-t border-[#d9e2e6] pt-5 text-xs leading-5 text-[#6c7d88] sm:flex-row sm:justify-between"><p>Deadlines, portals, funding and exchange rates can change. Reopen the official details before every submission.</p><p>Your edits are saved in this browser. Export a backup if you switch devices.</p></footer>
  </div></main>
}
